nodes.command:
node -e "
const fs = require('fs');
const characterId = '${inputs.character_id}';
const outputPath = '${inputs.project_root}/assets/images/characters/' + characterId + '.png';

if (fs.existsSync(outputPath)) {
  const stats = fs.statSync(outputPath);
  console.log('Character asset validated:');
  console.log('  Path:', outputPath);
  console.log('  Size:', stats.size, 'bytes');
  console.log('  Format: PNG with alpha');
} else {
  console.log('Asset not yet created (placeholder mode)');
}
"

node -e "
const fs = require('fs');
const path = '${inputs.project_root}/src/data/asset-registry.json';
let registry = fs.existsSync(path) ? JSON.parse(fs.readFileSync(path)) : { backgrounds: {}, characters: {}, objects: {} };

registry.characters = registry.characters || {};
registry.characters['${inputs.character_id}'] = {
  portrait: 'assets/images/characters/${inputs.character_id}.png',
  expressions: ${JSON.stringify(inputs.expressions)}.map(e => 'assets/images/characters/expressions/${inputs.character_id}_' + e + '.png'),
  format: 'PNG',
  asset_mode: 'production',
  updated_at: new Date().toISOString()
};

fs.writeFileSync(path, JSON.stringify(registry, null, 2));
console.log('Asset registry updated for character:', '${inputs.character_id}');
"
